#!/usr/bin/env python3
"""
Compute total revenue from sales data.

Supports:
 - CSV file with headers 'price' and 'quantity'
 - JSON file: list of objects with 'price' and 'quantity' or lists/tuples [price, quantity]
 - Or interactive mode reading lines 'price,quantity' from stdin

This script is self-contained, does not perform network or unsafe operations, and prints the total revenue.
"""

import argparse
import csv
import json
import sys
from decimal import Decimal, InvalidOperation


def parse_decimal(s):
    try:
        return Decimal(str(s))
    except (InvalidOperation, ValueError):
        raise ValueError(f"Invalid numeric value: {s}")


def compute_revenue(items):
    total = Decimal('0')
    for item in items:
        if isinstance(item, dict):
            price_raw = item.get('price')
            qty_raw = item.get('quantity')
        else:
            # assume sequence-like (price, quantity)
            try:
                price_raw = item[0]
                qty_raw = item[1]
            except Exception:
                raise ValueError(f"Invalid item format: {item}")
        price = parse_decimal(price_raw)
        qty = parse_decimal(qty_raw)
        total += price * qty
    return total


def read_csv(path):
    items = []
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames and 'price' in reader.fieldnames and 'quantity' in reader.fieldnames:
            for row in reader:
                items.append({'price': row['price'], 'quantity': row['quantity']})
        else:
            # fallback: treat each row as [price, quantity]
            f.seek(0)
            reader2 = csv.reader(f)
            for row in reader2:
                if not row:
                    continue
                if len(row) < 2:
                    raise ValueError(f"CSV row must have at least two columns (price,quantity): {row}")
                items.append((row[0], row[1]))
    return items


def read_json(path):
    with open(path) as f:
        data = json.load(f)
    if isinstance(data, list):
        items = []
        for elem in data:
            if isinstance(elem, dict) and 'price' in elem and 'quantity' in elem:
                items.append({'price': elem['price'], 'quantity': elem['quantity']})
            elif isinstance(elem, (list, tuple)) and len(elem) >= 2:
                items.append((elem[0], elem[1]))
            else:
                raise ValueError('JSON list items must be objects with price and quantity or arrays/tuples of length >= 2')
        return items
    else:
        raise ValueError('JSON file must contain a top-level list')


def read_stdin():
    items = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = [p.strip() for p in line.split(',')]
        if len(parts) < 2:
            raise ValueError(f"Expected 'price,quantity' per line, got: {line}")
        items.append((parts[0], parts[1]))
    return items


def main():
    parser = argparse.ArgumentParser(description="Compute total revenue from sales data.")
    parser.add_argument('--csv', help='Path to CSV file with price and quantity columns')
    parser.add_argument('--json', help='Path to JSON file (list of objects or arrays)')
    parser.add_argument('--stdin', action='store_true', help='Read price,quantity lines from stdin')
    args = parser.parse_args()

    items = []
    try:
        if args.csv:
            items = read_csv(args.csv)
        elif args.json:
            items = read_json(args.json)
        elif args.stdin:
            items = read_stdin()
        else:
            parser.print_help()
            sys.exit(1)

        total = compute_revenue(items)
        # Print using str() to preserve Decimal formatting; callers can parse as needed
        print(str(total))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(2)


if __name__ == '__main__':
    main()

